INSERT INTO "Artwork" (id,title,"updatedAt",source)
SELECT g, 'Synthetic benchmark artwork ' || g, now(), 'LOCAL_CREATED' FROM generate_series(1,21604) g;
INSERT INTO "Artist" (id,name,"updatedAt")
SELECT g, 'Synthetic creator ' || g, now() FROM generate_series(1,100) g;
INSERT INTO artwork_artists (id,"artworkId","artistId")
SELECT 'bench-membership-' || g,g,1+(g%100) FROM generate_series(1,21604) g;
INSERT INTO artwork_artist_evidence (id,"membershipId","evidenceKey",provenance,"updatedAt")
SELECT 'bench-evidence-' || g,'bench-membership-' || g,'manual','MANUAL',now() FROM generate_series(1,21604) g;
INSERT INTO "Image" (id,path,"artworkId","updatedAt","mediaType")
SELECT g,
 'fixture/media/artwork-' || (1+(g-1)/86) || '/' || md5(g::text) || '/' || repeat('synthetic-',5) || g ||
 CASE WHEN g%738=0 AND g<=1601*738 THEN (CASE WHEN g%1476=0 THEN '.MP4' ELSE '.mp4' END) ELSE '.jpg' END,
 1+(g-1)/86,now(),
 CASE WHEN g%738=0 AND g<=1601*738 THEN 'UNKNOWN'::"MediaType" ELSE 'IMAGE'::"MediaType" END
FROM generate_series(1,1855523) g;
INSERT INTO system_jobs (id,type,status,"definitionVersion",payload,"legacyDisplay","createdAt","updatedAt")
SELECT 'bench-job-' || lpad(g::text,6,'0'),
 CASE WHEN g<=40 THEN 'VIDEO_STREAMING_OPTIMIZATION' ELSE 'VIDEO_PROBE' END,
 'COMPLETED', CASE WHEN g<=20 THEN 0 ELSE 1 END,
 jsonb_build_object('imageId',CASE WHEN g<=40 THEN g*738 ELSE g END),
 CASE WHEN g<=20 THEN jsonb_build_object('targetImageId',g*738) ELSE NULL END,
 now() - interval '1 day',now()
FROM generate_series(1,31225) g;
SELECT setval(pg_get_serial_sequence('"Artwork"','id'),21604);
SELECT setval(pg_get_serial_sequence('"Image"','id'),1855523);
